  const near = maskOf(rects, 3);
  let removed = 0;
  for (const c of [...g]) {
    const [x, , z] = c.pos, yv = c.pos[1];
    if (prot.has(c.pos.join(",")) || inKeep(c.pos)) continue;
    const k = K(x, z);
    if ((yv >= yy && near.has(k)) || (yv === yy - 1 && near.has(k) && !mask.has(k) && /_(stairs|slab)$/.test(c.block))) { g.unset(...c.pos); removed++; }
  }
  const r = o.preset ? roof(g, rects, o.preset, { ...o, ...(style ? { style } : {}), y: yy, keep, protect: prot }) : roof(g, rects, style ?? "hip", { ...o, y: yy, keep, protect: prot });
  return { ...r, detected: { eave: det.eave, y: yy, rects, area: det.area, removed } };
}
